    #expect(variants.count == 3, "enum_task_phase: oracle variant count")
    guard variants.count == 3 else {
        return
    }

    #expect(try oracleText(variants[0].member("name")) == "todo", "enum_task_phase variant 0 name")
    #expect(
        try oracleNumberText(variants[0].member("value")) == String(EnumTaskPhase.todo.rawValue),
        "enum_task_phase.todo"
    )
    // The name the declaration answers is the one the document wrote.
    #expect(EnumTaskPhase.todo.declaredName == "todo", "enum_task_phase.todo declared name")
    #expect(try oracleText(variants[1].member("name")) == "in_review", "enum_task_phase variant 1 name")
